    function translate(value) {
        const trimmed = value.trim();
        if (!trimmed) return value;
        const translated = translations[trimmed];
        if (translated) return value.replace(trimmed, translated);
        for (const [pattern, replacement] of textPatterns) {
            if (pattern.test(trimmed)) return trimmed.replace(pattern, replacement);
        }
        return value;
    }
    // Native browser dialogs do not create DOM nodes, so MutationObserver cannot translate them.
    // Wrap them once, keeping their native return values and behavior intact.
    if (!window.__ghmDialogsTranslated) {
        window.__ghmDialogsTranslated = true;
        const translateDialog = value => localStorage.getItem(STORAGE_KEY) === 'en' ? translate(value) : value;
        const nativeAlert = typeof window.alert === 'function' ? window.alert.bind(window) : null;
        const nativeConfirm = typeof window.confirm === 'function' ? window.confirm.bind(window) : null;
        const nativePrompt = typeof window.prompt === 'function' ? window.prompt.bind(window) : null;
        if (nativeAlert) window.alert = message => nativeAlert(translateDialog(String(message ?? '')));
        if (nativeConfirm) window.confirm = message => nativeConfirm(translateDialog(String(message ?? '')));
        if (nativePrompt) window.prompt = (message, defaultValue) => nativePrompt(translateDialog(String(message ?? '')), defaultValue);
    }
    function visit(node, english) {
        if (node.nodeType === Node.TEXT_NODE) {
            if (!spanishText.has(node)) spanishText.set(node, node.nodeValue || '');
            const source = spanishText.get(node);
            const output = english ? translate(source) : source;
            if (node.nodeValue !== output) {
                translatingTextNodes.add(node);
                node.nodeValue = output;
            }
            return;
        }
        if (node.nodeType !== Node.ELEMENT_NODE && node !== document.body) return;
        if (node.nodeType === Node.ELEMENT_NODE) {
            for (const name of ['placeholder', 'title', 'aria-label']) {
                if (!node.hasAttribute(name)) continue;
                let values = spanishAttrs.get(node);
                if (!values) { values = {}; spanishAttrs.set(node, values); }
                if (!(name in values)) values[name] = node.getAttribute(name);
                const output = english ? translate(values[name]) : values[name];
                if (node.getAttribute(name) !== output) {
                    let pending = translatingAttributes.get(node);
                    if (!pending) { pending = new Set(); translatingAttributes.set(node, pending); }
                    pending.add(name);
                    node.setAttribute(name, output);
                }
            }
        }
        node.childNodes?.forEach(child => visit(child, english));
    }
    function setLanguage(language) {
        const english = language === 'en';
        localStorage.setItem(STORAGE_KEY, english ? 'en' : 'es');
        document.documentElement.lang = english ? 'en' : 'es';
        visit(document.body, english);
        const selector = document.getElementById('cfg-language');
        if (selector) selector.value = english ? 'en' : 'es';
    }
    window.ghmSetLanguage = setLanguage;
    window.ghmTranslateText = value => localStorage.getItem(STORAGE_KEY) === 'en' ? translate(String(value ?? '')) : String(value ?? '');
    const observer = new MutationObserver(records => {
        const english = localStorage.getItem(STORAGE_KEY) === 'en';
        for (const record of records) {
            if (record.type === 'characterData' && record.target) {
                if (translatingTextNodes.has(record.target)) {
                    translatingTextNodes.delete(record.target);
                    continue;
                }
                spanishText.set(record.target, record.target.nodeValue || '');
                visit(record.target, english);
                continue;
            }
            if (record.type === 'attributes' && record.target && record.attributeName) {
                const pending = translatingAttributes.get(record.target);
                if (pending?.has(record.attributeName)) {
                    pending.delete(record.attributeName);
                    continue;
                }
                const values = spanishAttrs.get(record.target) || {};
                values[record.attributeName] = record.target.getAttribute(record.attributeName) || '';
                spanishAttrs.set(record.target, values);
                visit(record.target, english);
                continue;
            }
            if (english) record.addedNodes.forEach(node => visit(node, true));
        }
    });
    observer.observe(document.body, { childList: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'title', 'aria-label'], subtree: true });
